package br.com.confirmacao.professional.api;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.professional.application.ProfessionalService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/professionals") public class ProfessionalController{private final ProfessionalService service;private final AuditService audit;public ProfessionalController(ProfessionalService s,AuditService a){service=s;audit=a;}@GetMapping("/me")public ProfessionalResponse me(JwtAuthenticationToken jwt){return ProfessionalResponse.from(service.findById(id(jwt)));}@PutMapping("/me")public ProfessionalResponse update(JwtAuthenticationToken jwt,@Valid@RequestBody UpdateMyProfileRequest q,HttpServletRequest h){UUID id=id(jwt);var p=service.updateProfile(id,q.fullName(),q.email(),q.phone(),q.registrationNumber(),q.specialty(),q.displayName(),q.timezone(),q.defaultSessionMinutes(),q.defaultModality(),q.remindersEnabled());audit.record(AuditAction.PROFESSIONAL_UPDATED,"PROFESSIONAL",id,h);return ProfessionalResponse.from(p);}private UUID id(JwtAuthenticationToken j){return UUID.fromString(j.getToken().getClaimAsString("professional_id"));}}
